code:
import java.util.*;
public class Main {
    static class Store {
        int version=0, postCount=0;
        Map<String,String> data=new LinkedHashMap<>();
        void put(String k,String v){ data.put(k,v); version++; }
        void post(String v){ postCount++; data.put("item"+postCount,v); }
    }
    public static void main(String[] a){
        Store s=new Store();
        s.put("x","A");
        String before=s.data.toString();
        s.put("x","A");
        String afterSame=s.data.toString();
        s.put("x","B");
        String afterChange=s.data.toString();
        System.out.println("before: "+before);
        System.out.println("after same PUT: "+afterSame);
        System.out.println("PUT idempotent (same value)? "+before.equals(afterSame));
        System.out.println("after change PUT: "+afterChange);
        Store p=new Store();
        p.post("n"); p.post("n");
        System.out.println("POST count (not idempotent): "+p.postCount);
    }
}
